  "land.f.pages.title": "Jeder Spieler im Web",
  "land.f.pages.text": "Rund 17.500 Datenbankseiten: jeder Spieler mit Attributen, CA/PA, Wunderkindern und Bosman-Transfers – kostenlos zum Stöbern.",
  "land.check.beta": "Beta",
  "land.alt.start": "Das Startmenü von CM 01/02",
